let _emailChanged;
function wireEmailOnChange(executionContext) {
  const formContext = executionContext.getFormContext();
  const attr = formContext.getAttribute("emailaddress1");
  if (!attr || _emailChanged) return;
  _emailChanged = () => console.log("Email changed:", attr.getValue());
  attr.addOnChange(_emailChanged);
}
function unwireEmailOnChange(executionContext) {
  const formContext = executionContext.getFormContext();
  const attr = formContext.getAttribute("emailaddress1");
  if (attr && _emailChanged) {
    attr.removeOnChange(_emailChanged);
    _emailChanged = null;
  }
}

function tweakField(executionContext) {
  const formContext = executionContext.getFormContext();
  const ctrl = formContext.getControl("telephone1");
  ctrl?.setFocus();
  ctrl?.setVisible(true);
  ctrl?.setDisabled(false); // or true
}

function refreshRibbon(executionContext) {
