  formContext.ui.refreshRibbon();
}

function isCreateForm(executionContext) {
  const formContext = executionContext.getFormContext();
  return formContext.ui.getFormType() === 1; // 1=create, 2=update
}

function setPhoneRequired(executionContext, required) {
  const formContext = executionContext.getFormContext();
  const attr = formContext.getAttribute("telephone1");
  attr?.setRequiredLevel(required ? "required" : "none"); // or "recommended"
}

function wireDataLoad(executionContext) {
  const formContext = executionContext.getFormContext();
  const onDataLoad = () => console.log("Form data loaded/reloaded");
  formContext.data.addOnLoad(onDataLoad);
  // Remove later: formContext.data.removeOnLoad(onDataLoad);
}

async function saveIfDirty(executionContext) {
  const formContext = executionContext.getFormContext();
  if (formContext.data.entity.getIsDirty()) {
    await formContext.data.save();
  }
}

