async function withProgressIndicator(fn) {
  try {
    Xrm.Utility.showProgressIndicator("Working…");
    await fn();
  } finally {
    Xrm.Utility.closeProgressIndicator();
  }
}

function onSave(executionContext) {
  const args = executionContext.getEventArgs();
  // 70 = auto-save (30s timer or navigating away)
  if (args.getSaveMode() === 70) {
    args.preventDefault();
  }
}

function toggleDetailsTab(executionContext, visible) {
  const formContext = executionContext.getFormContext();
  const tab = formContext.ui.tabs.get("DETAILS_TAB");
  if (!tab) return;
  tab.setVisible(!!visible);
  tab.sections.get("ADDRESS")?.setVisible(!!visible);
}

function showError(executionContext) {
  const formContext = executionContext.getFormContext();
  const id = "err.my.unique.id";
  formContext.ui.setFormNotification("Something went wrong.", "ERROR", id);
  setTimeout(() => formContext.ui.clearFormNotification(id), 4000);
}

function markEmailInvalid(executionContext) {
  const formContext = executionContext.getFormContext();
  const ctrl = formContext.getControl("emailaddress1");
  ctrl.setNotification("Invalid email format", "email.err");
  // later: ctrl.clearNotification("email.err");
}

function onPrimaryContactOnLoad(executionContext) {
  const formContext = executionContext.getFormContext();
  const ctrl = formContext.getControl("primarycontactid");
  if (!ctrl) return;
  ctrl.addPreSearch(() => {
    const accountId = formContext.data.entity.getId().replace(/[{}]/g, "");
    const filter = `<filter type="and">
      <condition attribute="parentcustomerid" operator="eq" value="${accountId}" />
      <condition attribute="statecode" operator="eq" value="0" />
    </filter>`;
    ctrl.addCustomFilter(filter, "contact");
  });
}

let _preSearchAdded = false;
let _preSearchHandler;

function wireLookup(executionContext) {
  const formContext = executionContext.getFormContext();
  const ctrl = formContext.getControl("primarycontactid");
  if (!ctrl || _preSearchAdded) return;
  _preSearchHandler = () => { /* ctrl.addCustomFilter(...) */ };
  ctrl.addPreSearch(_preSearchHandler);
  _preSearchAdded = true;
}

function unwireLookup(executionContext) {
  const formContext = executionContext.getFormContext();
  const ctrl = formContext.getControl("primarycontactid");
  if (ctrl && _preSearchAdded && _preSearchHandler) {
    try { ctrl.removePreSearch(_preSearchHandler); } catch {}
    _preSearchAdded = false;
    _preSearchHandler = null;
  }
}

