async function getAccountName(accountId) {
  const q = "?$select=name,telephone1";
  const rec = await Xrm.WebApi.retrieveRecord("account", accountId, q);
  return rec.name;
}

async function getActiveContactsByAccount(accountId) {
  const odata = `?$select=fullname,emailaddress1
    &$filter=statecode eq 0 and _parentcustomerid_value eq ${accountId}
    &$orderby=fullname asc`;
  const res = await Xrm.WebApi.retrieveMultipleRecords("contact", odata);
  return res.entities;
}

async function createAndUpdateAccount() {
  const created = await Xrm.WebApi.createRecord("account", { name: "Contoso" });
  await Xrm.WebApi.updateRecord("account", created.id, { telephone1: "555-0100" });
  return created.id;
}

async function relateContactToAccount(accountId, contactId) {
  await Xrm.WebApi.associate("account", accountId, "account_primary_contact", [
    { id: contactId, entityType: "contact" }
  ]);
}
async function unrelateContactFromAccount(accountId, contactId) {
  await Xrm.WebApi.disassociate("account", accountId, "account_primary_contact", contactId);
}

async function qualifyLead(leadId) {
  const req = {
    entity: { entityType: "lead", id: leadId },
    getMetadata: () => ({
      boundParameter: "entity",
      parameterTypes: { entity: { typeName: "mscrm.lead", structuralProperty: 5 } },
      operationName: "QualifyLead",
      operationType: 0 // Action
    })
  };
  const resp = await Xrm.WebApi.online.execute(req);
  if (resp.ok) console.log("Lead qualified");
}

async function whoAmI() {
  const req = {
    getMetadata: () => ({
      boundParameter: null,
      parameterTypes: {},
      operationName: "WhoAmI",
      operationType: 1 // Function
    })
  };
  const resp = await Xrm.WebApi.online.execute(req);
  return await resp.json();
}

async function batchCreateContacts() {
  const reqs = [1,2,3].map(i => ({
    entity: { firstname: "John", lastname: "Batch"+i },
    getMetadata: () => ({
      boundParameter: null,
      parameterTypes: { entity: { typeName: "mscrm.contact", structuralProperty: 5 } },
      operationName: "Create",
      operationType: 2 // CRUD
    })
  }));
  return await Xrm.WebApi.online.executeMultiple(reqs);
}

async function setPrimaryContactViaBind(accountId, contactId) {
  const payload = { "primarycontactid@odata.bind": `/contacts(${contactId})` };
  await Xrm.WebApi.updateRecord("account", accountId, payload);
}

async function topAccountsByRevenue() {
  const fetchXml = [
    "<fetch top='5'>",
    "  <entity name='account'>",
    "    <attribute name='name' />",
    "    <attribute name='revenue' />",
    "    <order attribute='revenue' descending='true' />",
    "    <filter><condition attribute='statecode' operator='eq' value='0' /></filter>",
    "  </entity>",
    "</fetch>"
  ].join("");
  const res = await Xrm.WebApi.retrieveMultipleRecords("account", "?fetchXml=" + encodeURIComponent(fetchXml));
  return res.entities;
}

async function readContactDisplay(contactId) {
  const rec = await Xrm.WebApi.retrieveRecord("contact", contactId,
    "?$select=fullname,statuscode,_parentcustomerid_value");
  const FV = "@OData.Community.Display.V1.FormattedValue";
  return {
    name: rec.fullname,
    status: rec["statuscode" + FV],                   // choice label
    accountName: rec["_parentcustomerid_value" + FV], // lookup display name
    accountId: rec._parentcustomerid_value            // lookup id
  };
}

async function safeRetrieve(id) {
  try {
    return await Xrm.WebApi.retrieveRecord("account", id, "?$select=name");
  } catch (error) {
    // error = { errorCode: Number, message: String }
    console.error(`Web API failed (${error.errorCode}): ${error.message}`);
    await Xrm.Navigation.openErrorDialog({ message: error.message });
    return null;
  }
}

