function refreshContactsGrid(executionContext) {
  const formContext = executionContext.getFormContext();
  formContext.getControl("Contacts")?.refresh();
}

function getSelectedContacts(executionContext) {
  const formContext = executionContext.getFormContext();
  const grid = formContext.getControl("Contacts")?.getGrid();
  if (!grid) return;
  grid.getSelectedRows().forEach(row => {
    const id = row.getId();
    const name = row?.getData()?.getEntity()?.getPrimaryAttributeValue?.();
    console.log("Selected:", name, id);
  });
}

function wireGridOnLoad(executionContext) {
  const formContext = executionContext.getFormContext();
  const gridCtrl = formContext.getControl("Contacts");
  if (!gridCtrl) return;
  const handler = () => console.log("Grid loaded/updated");
  gridCtrl.addOnLoad(handler);
  // Remove later: gridCtrl.removeOnLoad(handler);
}

async function showGlobalWarning() {
  const id = await Xrm.App.addGlobalNotification({
    type: 2,      // 2 = message bar (only supported type)
    level: 3,     // 1=success, 2=error, 3=warning, 4=info
    message: "Records are read-only during maintenance.",
    showCloseButton: true,
    action: {
      actionLabel: "Learn more",
      eventHandler: () => Xrm.Navigation.openUrl("https://learn.microsoft.com/power-apps/")
    }
  });
  // later: await Xrm.App.clearGlobalNotification(id);
  return id;
}

async function openContactSidePane(contactId) {
  const pane = await Xrm.App.sidePanes.createPane({
    title: "Contact",
    paneId: "contactPane", // reuse the same pane on repeat calls
    canClose: true,
    width: 400             // pixels (minimum 300)
  });
  await pane.navigate({
    pageType: "entityrecord",
    entityName: "contact",
    entityId: contactId
  });
}

function logContext() {
  const ctx = Xrm.Utility.getGlobalContext();
  console.log("User:", ctx.userSettings.userName, ctx.userSettings.userId);
  console.log("Org:", ctx.organizationSettings.uniqueName, ctx.organizationSettings.organizationId);
}

function userHasRole(roleId) {
  const roles = Xrm.Utility.getGlobalContext().userSettings.securityRoles || [];
  // roleId must be a GUID without braces
  return roles.some(r => r.toLowerCase() === roleId.toLowerCase());
}

function getUserRoleNames() {
  const roles = Xrm.Utility.getGlobalContext().userSettings.roles;
  const names = [];
  roles.forEach(r => names.push(r.name));
  return names;
}

function getCurrentPage() {
  const input = Xrm.Utility.getPageContext()?.input || {};
  return {
    pageType: input.pageType,     // "entityrecord" | "entitylist"
    entityName: input.entityName,
    entityId: input.entityId      // form only
  };
}
